/* English text for data/qcm/physique.js (physics course questions, merged by id over the French bank).
   Vocabulary and notation of the official English course (Physics S1, Part 1: Classical Mechanics): reference frame
   (Galilean, terrestrial), material point, equations of motion, trajectory equation, Newton’s first / second / third
   law, weight W⃗ (P⃗ in French), surface reaction force, tension in a string, work W_A→B, driving / resisting work,
   work-kinetic energy theorem, kinetic energy E_k (Ec in French), potential energy E_p, mechanical energy E_M,
   polar coordinates, moving basis, anti-clockwise. Decimal points. Same notation as the French file:
   {v} = vector, `x` = quantity in italics, subscript after “_”. Options left out are formulas, kept from French. */
REV.i18n.topics({
  'phys-cadre': 'Study framework',
  'phys-pva': 'Position, velocity, acceleration',
  'phys-mouvement': 'Nature of motion',
  'phys-integrer': 'Equations of motion, integration',
  'phys-trajectoire': 'Trajectory equation',
  'phys-tir': 'Projectile motion and free fall',
  'phys-vecteurs': 'Components and scalar product',
  'phys-forces': 'Forces',
  'phys-newton': 'Newton’s laws',
  'phys-travail': 'Work and power',
  'phys-energie': 'Energy: Ek, Ep, EM',
  'phys-polaires': 'Polar coordinates and basis (not in midterm 1)',
  'phys-polaires-va': 'Polar velocity and acceleration (not in midterm 1)',
  'phys-circulaire': 'Circular motion in polar coordinates (not in midterm 1)',
  'phys-unites': 'Units and dimensional consistency'
});
(function () {
  var FIG = window.PHYS_QFIG || {};
  var SLOPE = FIG.incline ? FIG.incline('Slope at an angle α to the ground. The robot M stands on the slope. The vector u x points down the slope, the vector u y is perpendicular to the slope, pointing up; the weight W is vertical, pointing down.', 'W') : null;

  var E = {
    /* ================= chapter 1: Cartesian kinematics ================= */
    'phys-c1-01': { q: 'A reference frame is called Galilean if…',
      o: ['it does not undergo any acceleration', 'it is attached to the Earth', 'its axes are orthonormal', 'its origin is the starting point of the moving object'],
      x: 'This is Definition 2 of the course. The terrestrial reference frame is only “assumed Galilean”: we accept it for short motions (a ball, a car). Orthonormal axes and an origin are the choice of coordinate system, not a property of the reference frame.' },
    'phys-c1-02': { q: 'You can model a system as a material point when…',
      o: ['you can neglect both its size and its rotation about itself', 'its mass is small', 'it is at rest', 'it moves in a straight line'],
      x: 'Definition 1 of the course. It depends on the problem: the Earth orbiting the Sun is a material point (its radius is small compared with the Earth-Sun distance); the Earth spinning about itself (length of the day) is not. Mass has nothing to do with it.' },
    'phys-c1-03': { q: 'What do you state at the start of your answer, before the first equation?',
      o: ['the system under study', 'the reference frame', 'the coordinate system: origin and axes', 'the origin of time, the instant `t` = 0', 'the mass of the system, in kg'],
      x: 'These are the first lines expected (TD 1, Ex 3: “describe the study framework”). For example: system, the projectile modelled as a point M; terrestrial reference frame, assumed Galilean; coordinate system (O, {u_x}, {u_y}) with {u_y} pointing up; `t` = 0 at launch. The mass is not part of it: it can stay as a letter, and kinematics does not need it.' },
    'phys-c1-04': { q: '“A passenger sitting in a moving train is at rest.” This sentence is true whatever the reference frame.',
      x: 'False. The passenger is at rest in the train’s reference frame, but moves at the speed of the train in the terrestrial reference frame. Motion only makes sense relative to a reference frame: that is why you always state it.' },
    'phys-c1-05': { q: 'The equations of motion of a point are `x`(`t`) = 2`t` and `y`(`t`) = `t`² − 1 (in m, `t` in s). What is the position vector at `t` = 2 s?',
      x: 'Replace `t` with 2 in each coordinate: `x`(2) = 4 and `y`(2) = 4 − 1 = 3. A vector is written with the unit vectors, not as a number: adding 4 and 3 makes no sense. 2 {u_x} + 4 {u_y} is the velocity at `t` = 2 s (derivatives 2 and 2`t`), not the position.' },
    'phys-c1-06': { q: 'A point M has coordinates (3, 4), in metres. How far is it from the origin O?',
      x: 'The distance OM is the norm of the position vector: OM = √(`x`² + `y`²) = √(9 + 16) = √25 = 5 m. Not 3 + 4 = 7 m: you do not add the coordinates.' },
    'phys-c1-07': { q: 'A car is parked 7 m from the front door of the house (TD 1, Ex 1). The origin O is the door, the axis follows the road, pointing from the door towards the car, and `t` = 0 when the car starts. What is `x`(0)?',
      o: ['7 m', '0 m, since the car has not moved yet', '−7 m', 'you cannot know without the velocity'],
      x: '`x` is the position relative to O, not the distance travelled. When it starts, the car has not travelled yet, but it is 7 m from the door, on the positive `x` side: `x`(0) = 7 m. It is the “+ 7” in `x`(`t`) = 1.25 `t`² + 7.' },
    'phys-c1-08': { q: 'The equations of motion are `x`(`t`) = 3`t`² + 2 and `y`(`t`) = 4`t` (in m, `t` in s). What is the velocity vector?',
      x: 'In Cartesian coordinates, {u_x} and {u_y} are fixed: you differentiate each coordinate. (3`t`²)′ = 6`t` (the exponent comes down as a factor), the constant 2 disappears, (4`t`)′ = 4. 6 {u_x} is the acceleration: one derivative too many.' },
    'phys-c1-09': { q: 'A point has velocity {v} = 6 {u_x} + 8 {u_y}, in m·s⁻¹. What is its speed, that is the norm ‖{v}‖?',
      x: '‖{v}‖ = √(`v_x`² + `v_y`²) = √(36 + 64) = √100 = 10 m·s⁻¹. Not 6 + 8 = 14: the two components are perpendicular, so use Pythagoras.' },
    'phys-c1-10': { q: '`x`(`t`) = 5 cos(2`t`). What is `ẋ`?',
      x: 'Chain rule: (cos `u`)′ = −`u`′ sin `u`, with `u` = 2`t` and `u`′ = 2. So `ẋ` = 5 × (−2 sin(2`t`)) = −10 sin(2`t`). Forgetting the factor 2 or the minus sign are the two classic mistakes; equations in cos(ω`t`) and sin(ω`t`) come up in most midterms.' },
    'phys-c1-11': { q: 'The velocity vector {v} of a point M is always…',
      o: ['tangent to the trajectory, in the direction of motion', 'collinear to the position vector {OM}', 'pointing towards the origin O', 'perpendicular to the trajectory'],
      x: 'During d`t`, M moves by d{OM}, a tiny piece of trajectory: {v} = d{OM}/d`t` is collinear to this displacement, so it is tangent to the trajectory. There is no reason for it to be aligned with {OM}, which depends on the choice of origin. (The English course adds “that is, the position vector” after “displacement”: that bracket is wrong.)' },
    'phys-c1-12': { q: 'The high-speed train of TD 1 travels at 90 km/h. What is that in m·s⁻¹?',
      x: '1 km/h = 1000 m in 3600 s = 1/3.6 m·s⁻¹. To convert km/h into m·s⁻¹, divide by 3.6: 90/3.6 = 25 m·s⁻¹. Multiplying would give 324 m·s⁻¹, more than 1000 km/h.' },
    'phys-c1-13': { q: 'A point has velocity {v} = 6`t` {u_x} + 4 {u_y} (in m·s⁻¹). What is its acceleration?',
      x: '{a} = d{v}/d`t`: differentiate each component. (6`t`)′ = 6 and (4)′ = 0: a constant velocity component gives zero acceleration on that axis. 3`t`² {u_x} + 4`t` {u_y} is an antiderivative: you integrated instead of differentiating.' },
    'phys-c1-14': { q: 'How do you know whether a motion is accelerated or decelerated?',
      o: ['from the sign of the scalar product {v} · {a}', 'from the sign of the acceleration alone', 'from the sign of the position `x`', 'by checking whether the trajectory is a straight line'],
      x: 'Course: {v} · {a} > 0, the motion is accelerated (the speed increases); {v} · {a} &lt; 0, it is decelerated; {v} · {a} = 0 with {a} ≠ {0}, only the direction changes. The sign of the acceleration alone is not enough: a falling ball has `a_y` = −`g` &lt; 0, and yet it goes faster and faster.' },
    'phys-c1-15': { q: 'After the apex of a projectile motion, the ball comes down: `v_y` &lt; 0 and {a} = −`g` {u_y}, with {u_y} pointing up. On the vertical axis, its motion is…',
      o: ['accelerated', 'decelerated, because the acceleration is negative', 'decelerated, because the ball goes down', 'uniform'],
      x: '`v_y` and `a_y` = −`g` are both negative: their product is positive, the motion is accelerated (the ball goes faster and faster downwards). On the way up, `v_y` > 0 and `a_y` &lt; 0: decelerated. The sign of `a_y` alone tells you nothing.' },
    'phys-c1-16': { q: 'A Formula 1 car goes from 0 to 180 km/h in 4 s (TD 1, Ex 2). What is its average acceleration?',
      x: 'First in SI units: 180 km/h = 180/3.6 = 50 m·s⁻¹. Then `a`<sub>avg</sub> = Δ`v`/Δ`t` = 50/4 = 12.5 m·s⁻², about 1.25 `g`. 180/4 = 45 gives km/h per second, not m·s⁻². The TD answer key rounds it to 12 m·s⁻² and 1.2 `g`.' },
    'phys-c1-17': { q: 'A uniform rectilinear motion has…',
      o: ['zero acceleration', 'a constant, non-zero acceleration', 'a velocity that increases steadily', 'a constant position'],
      x: 'Rectilinear: the trajectory is a straight line, the direction of {v} does not change. Uniform: the norm of {v} is constant. So {v} is a constant vector and {a} = {0}. A constant non-zero acceleration is a uniformly varied motion; a constant position is rest.' },
    'phys-c1-18': { q: 'The car of TD 1 has position `x`(`t`) = 1.25 `t`² + 7 (in m, `t` in s). What distance has it travelled between `t` = 0 and `t` = 4 s?',
      x: '`x`(4) = 1.25 × 16 + 7 = 27 m: that is the position. The car started from `x`(0) = 7 m and always moves in the same direction: distance travelled = 27 − 7 = 20 m. The TD answer key says 27 m, which is the position, not the distance.' },
    'phys-c1-19': { q: 'On an axis, `x`(`t`) = 2`t`² − 8`t` + 1 (in m, `t` in s). Between `t` = 0 and `t` = 2 s, the motion is…',
      o: ['decelerated', 'accelerated, because `a` = 4 m·s⁻² is positive', 'accelerated, because `x` decreases', 'uniform'],
      x: '`v` = 4`t` − 8, negative for `t` &lt; 2 s; `a` = 4 m·s⁻², positive. Opposite signs: `v a` &lt; 0, the object slows down. It stops at `t` = 2 s, then moves back towards increasing `x`: from then on the motion is accelerated. The sign of `a` alone, or whether `x` increases, is not enough.' },
    'phys-c1-20': { q: 'On an axis, `x`(`t`) = 3`t` + 2 (in m, `t` in s). Which statements are correct?',
      o: ['the motion is uniform and rectilinear', 'the velocity is 3 m·s⁻¹', 'the acceleration is zero', 'the initial position is zero', 'the velocity is 5 m·s⁻¹ at `t` = 1 s'],
      x: '`v` = 3 m·s⁻¹, constant, and `a` = 0: uniform rectilinear motion. The initial position is `x`(0) = 2 m, not 0. 5 m is the position at `t` = 1 s, not the velocity.' },
    'phys-c1-21': { q: 'On an axis, `a`(`t`) = −10 m·s⁻² and `v`(0) = 4 m·s⁻¹. What is `v`(`t`)?',
      x: 'Integrate: `v`(`t`) = −10`t` + `C`. At `t` = 0, `v`(0) = `C` = 4. The constant is the initial velocity: setting it to 0 out of habit is the most common mistake. −5`t`² comes from integrating once too often.' },
    'phys-c1-22': { q: 'On the vertical axis, `v_y`(`t`) = −`g t` + `v_0` and `y`(0) = `h`. What is `y`(`t`)?',
      x: 'An antiderivative of −`g t` is −½ `g t`² (not −`g t`²: differentiate to check), an antiderivative of `v_0` is `v_0` `t`. The constant is set by `y`(0) = `h`: without it, the point would start from the ground.' },
    'phys-c1-23': { q: 'A point is released with no initial velocity 5 m above the ground. Axis {u_y} pointing up, O on the ground, `g` = 10 m·s⁻². After how long does it hit the ground?',
      x: 'This is the example of the course: `a` = −`g`, `v`(`t`) = −`g t` (zero initial velocity), `y`(`t`) = 5 − 5`t`². On the ground, `y`(`T`) = 0, so `T`² = 1 and `T` = 1 s. In general, `T` = √(2`h`/`g`), not √(2`h`)/`g`.' },
    'phys-c1-24': { q: 'A stone is in free fall: {a} = {g}, vertical, pointing down. You choose the axis {u_y} pointing down. What is `a_y`?',
      o: ['+`g`', '−`g`', '0', 'it depends on the mass of the stone'],
      x: '{g} points down, in the same direction as {u_y}: `a_y` = +`g`. The course takes {u_y} pointing up, and then `a_y` = −`g`. The sign depends on the axis: draw it before writing the projection. Mass plays no role in free fall.' },
    'phys-c1-25': { q: '`x`(`t`) = 2`t` and `y`(`t`) = 4`t`² (in m). What is the trajectory equation?',
      x: 'Isolate `t` in the simpler equation: `t` = `x`/2. Substitute: `y` = 4 (`x`/2)² = 4`x`²/4 = `x`². The square applies to the whole quotient. A trajectory equation links `y` and `x`: no `t` may remain.' },
    'phys-c1-26': { q: 'In the trajectory equation `y`(`x`), the time `t` must no longer appear.',
      x: 'True. The trajectory is the curve drawn by the point, without the time information: you eliminate `t` between `x`(`t`) and `y`(`t`). A `t` left in “`y`(`x`)” is a mistake.' },
    'phys-c1-27': { q: 'November 2017 midterm: `x`(`t`) = 1 + `R` sin(ω`t`) and `y`(`t`) = 2 + `R` cos(ω`t`), with `R` > 0 and ω constants. The trajectory is…',
      o: ['a circle with centre (1, 2) and radius `R`', 'a circle with centre O and radius `R`', 'an ellipse', 'a straight line'],
      x: 'sin(ω`t`) = (`x` − 1)/`R` and cos(ω`t`) = (`y` − 2)/`R`. Since sin² + cos² = 1: (`x` − 1)² + (`y` − 2)² = `R`². It is a circle with centre (1, 2), not O: the constants 1 and 2 shift the centre. Always give the shape of the trajectory and its features (centre, radius).' },
    'phys-c1-28': { q: 'A projectile is launched from the ground with `v_0` = 20 m·s⁻¹, at α = 30° above the horizontal (`g` = 10 m·s⁻², sin 30° = ½). At what time does it reach the apex?',
      x: 'At the apex, the vertical velocity is zero: `v_y` = `v_0` sin α − `g t` = 0, so `t`<sub>S</sub> = `v_0` sin α / `g` = 20 × ½ / 10 = 1 s. With cos α instead of sin α you would get 1.7 s: when α is measured from the horizontal, the vertical component takes the sine.' },
    'phys-c1-29': { q: 'Same launch: `v_0` = 20 m·s⁻¹, α = 30°, `g` = 10 m·s⁻², starting from the ground. What maximum height does it reach?',
      x: '`y`<sub>S</sub> = `y`(`t`<sub>S</sub>) = (`v_0` sin α) × 1 − 5 × 1² = 10 − 5 = 5 m. General formula: `y`<sub>S</sub> = `v_0`² sin² α / (2`g`) = 400 × ¼ / 20 = 5 m. Forgetting the square on sin α gives 10 m.' },
    'phys-c1-30': { q: 'At the apex of an oblique launch, the velocity vector is…',
      o: ['horizontal, with norm `v_0` cos α', 'zero', 'vertical', 'horizontal, with norm `v_0`'],
      x: 'At the apex, only `v_y` is zero. `v_x` = `v_0` cos α stays constant during the whole flight (no horizontal acceleration): {v} = `v_0` cos α {u_x}. The speed equals `v_0` only at launch.' },
    'phys-c1-31': { q: 'At the apex of a projectile’s trajectory, the acceleration is zero.',
      x: 'False. {a} = {g} = −`g` {u_y} at every point of the flight, apex included. At the apex, it is `v_y` that is zero, not the acceleration. If the acceleration were zero, the ball would fly off horizontally in a straight line.' },
    'phys-c1-32': { q: 'A projectile leaves the ground and lands on the ground again, with a fixed initial speed `v_0`. For which angle α is its range maximal?',
      x: 'The range is `x`<sub>P</sub> = `v_0`² sin(2α) / `g`, maximal when sin(2α) = 1, that is α = 45°. At 90° the projectile falls back on its starting point: zero range. 30° and 60° give the same, smaller range.' },

    /* ================= chapter 2: forces and Newton’s laws ================= */
    'phys-c2-01': { q: 'A force is measured in newtons (N). In SI units, 1 N equals…',
      x: 'From Σ{F} = `m` {a}: kg × m·s⁻². kg·m·s⁻¹ is the unit of momentum `m` {v}, and kg·m²·s⁻² that of an energy (the joule).' },
    'phys-c2-02': { q: 'What must you give to describe a force completely?',
      o: ['its norm, in N', 'its direction', 'its sense (which way it points)', 'its point of application', 'the velocity of the system'],
      x: 'A force is a vector: norm (its intensity, in newtons), direction, sense, and origin, its point of application, on the object subjected to the force. The velocity of the system is not part of it: a force can act on an object at rest. (The English course lists norm, direction and origin; the French one splits direction and sense.)' },
    'phys-c2-03': { q: 'Newton’s laws apply in…',
      o: ['a Galilean reference frame', 'any reference frame', 'a Cartesian coordinate system only', 'the reference frame attached to the system under study'],
      x: 'Each law starts with “in a Galilean reference frame”. The terrestrial reference frame is assumed Galilean for short motions. The coordinate system (Cartesian, polar) is a choice of coordinates, unrelated to whether the laws hold. In its own reference frame, the system is always at rest: that frame is not Galilean as soon as the system accelerates.' },
    'phys-c2-04': { q: 'A book lies at rest on a table. Which forces act on the book?',
      o: ['its weight {W} and the surface reaction force {R} of the table', 'its weight {W} only', 'its weight {W}, the reaction force {R} of the table and the force exerted by the book on the table', 'none, since it is at rest'],
      x: 'TD 2, Ex 1. The force diagram only includes the forces the system is subjected to. The force of the book on the table acts on the table. At rest does not mean “no force”: {W} and {R} cancel out, their sum is zero.' },
    'phys-c2-05': { q: 'A small ball hangs at rest from a string. Which forces act on the ball?',
      o: ['its weight {W}, vertical, pointing down', 'the tension {T} in the string, pointing from the ball towards the attachment point', 'the tension {T} in the string, pointing from the attachment point towards the ball', 'a surface reaction force {R} perpendicular to the string'],
      x: 'Two forces: the weight and the tension. Course: the tension has the direction of the string and points from the object towards the string; a string pulls, it never pushes. There is no surface, so no reaction force. At rest: {W} + {T} = {0}, so `T` = `m g`.' },
    'phys-c2-06': { q: 'Two perpendicular forces, of norms 3 N and 4 N, act on the same point. What is the norm of their sum (the net force)?',
      x: 'Forces add like vectors. Perpendicular, they form the sides of a right-angled triangle: ‖{F_1} + {F_2}‖ = √(3² + 4²) = 5 N. 7 N only holds if they point the same way along the same direction, 1 N if they point in opposite directions.' },
    'phys-c2-07': { q: 'What is the weight of an object of mass 2 kg? (`g` = 10 m·s⁻²)',
      x: '`W` = `m g` = 2 × 10 = 20 N. Mass (in kg) and weight (a force, in N) are two different quantities.' },
    'phys-c2-08': { q: 'The surface reaction force {R} of a surface, without friction, is always…',
      o: ['perpendicular to the surface', 'vertical, pointing up', 'opposite to the weight, with the same norm', 'parallel to the surface'],
      x: 'Course: the reaction force is always orthogonal to the surface; its norm is found case by case with Newton’s second law. On horizontal ground it is vertical and equals `m g` at equilibrium; on a slope of angle α it is tilted and equals `m g` cos α.' },
    'phys-c2-09': { q: 'With the axis {u_y} vertical and pointing up, the weight is written…',
      o: ['{W} = −`m g` {u_y}', '{W} = `m g` {u_y}', '{W} = −`g` {u_y}', '{W} = −`m g` {u_x}'],
      x: 'The weight is vertical, pointing down, with norm `m g`: it is opposite to {u_y}, hence the minus sign. Without `m`, it is the gravitational acceleration {g}, not the weight.' },
    'phys-c2-10': { q: 'The mass of an object is smaller on the Moon than on Earth.',
      x: 'False. Mass (in kg) measures how much a body resists being set in motion; it does not depend on the place. It is the weight `W` = `m g` that changes: `g` is about 1.6 m·s⁻² on the Moon, about 6 times less than on Earth.' },
    'phys-c2-11': { q: 'Friction from a fluid is written {f} = −α {v}, with α > 0. What does the “−” sign mean?',
      o: ['the force is opposite to the velocity', 'the force always points down', 'the coefficient α is negative', 'the force decreases over time'],
      x: 'TD 2, Ex 3. α is positive; the “−” says that {f} and {v} point in opposite directions: friction always opposes the motion. Projected on a vertical axis pointing up during a fall (`v_y` &lt; 0), it gives `f_y` = −α`v_y` > 0: upwards.' },
    'phys-c2-12': { q: 'In {f} = −α {v}, what is the unit of α?',
      x: 'By dimensional consistency: α = `f`/`v`, in N/(m·s⁻¹) = (kg·m·s⁻²)/(m·s⁻¹) = kg·s⁻¹. It is a question of TD 2 (Ex 3, part II).' },
    'phys-c2-13': { q: 'If the distance between two bodies doubles, the gravitational force between them is…',
      o: ['divided by 4', 'divided by 2', 'multiplied by 4', 'unchanged'],
      x: '`F` = `G m_1` `m_2`/`d`²: the force varies as 1/`d`². Distance × 2, so `d`² × 4 and force ÷ 4.' },
    'phys-c2-14': { q: 'What does the course say about the gravitational force between two bodies?',
      o: ['it is always attractive', 'its range is infinite', 'it can be repulsive, like the Coulomb force', 'it does not depend on the masses'],
      x: 'Always attractive, infinite range, proportional to the product of the masses and to 1/`d`². It is the Coulomb force that can be attractive or repulsive, because a charge can be negative; a mass is always positive.' },
    'phys-c2-15': { q: 'Two bodies of masses `m_1` and `m_2` are a distance `d` apart. {u} is the unit vector pointing from body 1 to body 2. What is the force exerted by body 1 on body 2?',
      x: 'The force is attractive: it pulls body 2 towards body 1, opposite to {u}, which points from 1 to 2. Hence the “−”. The course writes the formula without a “−” and without saying which way the unit vector points: remember this form, and always check that the force points towards the other body.' },
    'phys-c2-16': { q: 'By Newton’s first law (law of inertia), in a Galilean reference frame, a point subjected to no force, or to forces that cancel out…',
      o: ['stays at rest or keeps a uniform rectilinear motion', 'always ends up stopping', 'necessarily stays at rest', 'moves along a circle'],
      x: 'If it was at rest, it stays at rest; if it was moving, its motion is uniform and rectilinear. An object that slows down and stops is subjected to a force: friction.' },
    'phys-c2-17': { q: 'A car drives at a constant 90 km/h on a straight road. The sum of the forces acting on it is zero.',
      x: 'True. Uniform rectilinear motion: {v} is constant, {a} = {0}, so Σ{F} = `m` {a} = {0}. The driving force exactly balances friction. You need no force to keep your velocity, you need one to change it.' },
    'phys-c2-18': { q: 'A puck slides on perfectly smooth horizontal ice, with no friction at all. Once launched, it…',
      o: ['keeps going in a straight line at constant speed', 'slows down, since nothing pushes it any more', 'speeds up', 'turns'],
      x: 'On the puck: the weight {W} and the reaction force {R}, which cancel out. The sum of the forces is zero: uniform rectilinear motion (law of inertia). In reality, it slows down because of friction.' },
    'phys-c2-19': { q: 'For a system of constant mass, Newton’s second law is written…',
      x: 'Σ{F} = d{p}/d`t` = `m` {a}, in a Galilean reference frame. Σ{F} = {0} is the special case {a} = {0} (rest or uniform rectilinear motion). Σ{F} = `m` {g} only holds in free fall, when the weight is the only force.' },
    'phys-c2-20': { q: 'A 10 kg robot moves on horizontal ground, pushed by a horizontal force of 50 N; friction is neglected (TD 2, Ex 3). What is its acceleration?',
      x: 'On the horizontal axis, only the thrust acts ({W} and {R} are vertical and cancel out): `m a` = `F`, so `a` = 50/10 = 5 m·s⁻².' },
    'phys-c2-21': { q: 'In free fall, a heavy steel ball and a small marble fall with the same acceleration.',
      x: 'True. Only force: the weight. `m` {a} = `m` {g}, the mass cancels and {a} = {g} for any object. The course points it out: the acceleration does not depend on the mass of the object. In air, friction makes the difference.' },
    'phys-c2-22': { q: 'By Newton’s second law, the sum of the forces always has the same direction and sense as…',
      o: ['the acceleration', 'the velocity', 'the displacement', 'the position vector'],
      x: 'Σ{F} = `m` {a} with `m` > 0: the two vectors are collinear and point the same way. Not the velocity: a ball going up has an upward velocity, while the sum of the forces (its weight) points down.' },
    'phys-c2-23': { q: 'The momentum of a material point is…',
      o: ['{p} = `m` {v}, in kg·m·s⁻¹', '{p} = `m` {a}, in N', '½ `m v`², in J', '{p} = `m` {g}, in N'],
      x: 'Definition 6 of the course: {p} = `m` {v}, in kg·m·s⁻¹. Newton’s second law reads Σ{F} = d{p}/d`t`, which gives `m` {a} when the mass is constant. ½ `m v`² is the kinetic energy.' },
    'phys-c2-24': { q: 'The Earth attracts an apple with a force of 2 N. The apple attracts the Earth…',
      o: ['with a force of 2 N, pointing towards the apple', 'with a negligible force, since it is much lighter', 'with a force of 2 N, pointing towards the centre of the Earth', 'not at all'],
      x: 'Newton’s third law: {F_2→1} = −{F_1→2}. Same magnitude, opposite direction: the force of the apple on the Earth is 2 N and points towards the apple. What is negligible is the acceleration of the Earth (2 N for 6 × 10²⁴ kg), not the force.' },
    'phys-c2-25': { q: 'For a book lying on a table, the weight {W} of the book and the reaction force {R} of the table on the book form an action-reaction pair (Newton’s third law).',
      x: 'False. Both forces act on the same object, the book; an action-reaction pair involves two different objects. {W} and {R} cancel out because of the second law (equilibrium). The partner of {R} is the force of the book on the table; the partner of the weight is the pull of the book on the Earth.' },
    'phys-c2-26': { q: 'The two forces of an action-reaction pair…',
      o: ['act on two different bodies', 'act on the same body and cancel out', 'only exist between bodies in contact', 'only exist if the bodies move'],
      x: '{F_2→1} = −{F_1→2}: one acts on body 1, the other on body 2; that is why they do not cancel out. Gravity acts at a distance and also obeys the third law, at rest as well as in motion.' },
    'phys-c2-27': { q: 'A robot of mass `m` stands on a slope of angle α. Axes: {u_x} along the slope pointing down, {u_y} perpendicular to the slope pointing up (TD 2, Ex 2). What are the components of the weight {W}?',
      x: 'The angle between {W} (vertical) and the perpendicular to the slope is α, the same angle as the slope. So the perpendicular component is `m g` cos α, counted negative (towards the slope); the component along the slope is `m g` sin α, down the slope. Check with α = 0, horizontal ground: you must get (0 ; −`m g`). Swapping sin and cos is the most common mistake.' },
    'phys-c2-28': { q: 'The robot, of mass 10 kg, stays at rest on the slope of angle α = 30° (`g` = 10 m·s⁻², sin 30° = ½). What is the norm of the friction force holding it?',
      x: 'At equilibrium, {W} + {R} + {f} = {0}. On {u_x}, along the slope: `m g` sin α + `f_x` = 0, so `f_x` = −`m g` sin α. Friction points up the slope, with norm 10 × 10 × ½ = 50 N. On {u_y}: `R` = `m g` cos α ≈ 87 N.' },
    'phys-c2-29': { q: 'A point is in free fall; the axis {u_y} is vertical, pointing up. What does Newton’s second law give, projected on {u_y}?',
      o: ['−`m g` = `m a_y`, so `a_y` = −`g`', '`m g` = `m a_y`, so `a_y` = `g`', '−`m g` = `m v_y`', '−`m g` = 0'],
      x: 'Forces: the weight only, {W} = −`m g` {u_y}. Second law: {W} = `m` {a}, then projection on {u_y}: −`m g` = `m a_y`, that is `a_y` = −`g`. This is the method of the course (free fall from 5 m). The law gives the acceleration, not the velocity: you integrate afterwards.' },
    'phys-c2-30': { q: 'An object is at rest under its weight {W}, the reaction force {R} and a friction force {f}. What does Newton’s second law give?',
      o: ['{W} + {R} + {f} = {0}', '`W` + `R` + `f` = 0, adding the norms', '{W} = {R}', 'nothing: there is no motion'],
      x: 'At rest: {a} = {0}, so the vector sum of the forces is zero; you then project it on each axis. Norms do not add up: they are positive, their sum cannot be zero. And {W} = {R} is wrong: even without friction, you would have {W} = −{R}.' },
    'phys-c2-31': { q: 'The robot of TD 2 (Ex 3) is pushed by a constant force of 50 N and slowed down by {f} = −α {v}, with α = 0.5 kg·s⁻¹. What maximum speed does it reach?',
      x: 'At maximum speed, the velocity no longer changes: {a} = {0}, so the sum of the forces is zero. On the axis of motion: `F` − α`v`<sub>max</sub> = 0, hence `v`<sub>max</sub> = `F`/α = 50/0.5 = 100 m·s⁻¹.' },

    /* ================= chapter 3: work and energy ================= */
    'phys-c3-01': { q: 'What is the work of a constant force {F} when its point of application moves from A to B? (θ is the angle between {F} and {AB}.)',
      o: ['`W_A→B` = {F} · {AB} = `F` × AB × cos θ', '`W_A→B` = `F` × AB', '`W_A→B` = `F` × AB × sin θ', '`W_A→B` = `F` / AB'],
      x: 'The work of a constant force is the scalar product of the force and the displacement. Only the component of {F} along the displacement does work, hence cos θ. `F` × AB is only right if the force is parallel to the displacement and points the same way.' },
    'phys-c3-02': { q: 'A constant horizontal force of 10 N moves a trolley 3 m in its own direction. What is its work?',
      x: 'Force and displacement point the same way along the same direction: cos 0 = 1, `W` = 10 × 3 = 30 J. One joule is 1 N·m.' },
    'phys-c3-03': { q: 'A constant force of 3 N makes an angle of 60° with the displacement AB = 2 m (cos 60° = ½). What is its work?',
      x: '`W` = `F` × AB × cos 60° = 3 × 2 × ½ = 3 J. The angle to use is the one between the force and the displacement: if the problem gives the angle with the vertical, convert it first.' },
    'phys-c3-04': { q: 'A force perpendicular to the displacement, like the reaction force of horizontal ground on a sliding object…',
      o: ['does no work: `W` = 0', 'does driving (positive) work', 'does resisting (negative) work', 'does work equal to `F` × AB'],
      x: 'cos 90° = 0: a force perpendicular to the displacement does no work. It can curve the trajectory, but it does not change the speed.' },
    'phys-c3-05': { q: 'An object of mass `m` goes from height `z_A` to height `z_B` (vertical axis pointing up). What is the work done by its weight?',
      x: 'The weight is constant: `W_A→B` = {W} · {AB} = −`m g` (`z_B` − `z_A`) = `m g` (`z_A` − `z_B`). It only depends on the heights, not on the path. It is positive (driving) when the object goes down, negative (resisting) when it goes up. Swapping the two heights is the classic mistake. Careful with the letters: {W} is the weight, `W_A→B` the work.' },
    'phys-c3-06': { q: 'The weight of a 0.5 kg ball does work of +5 J (`g` = 10 m·s⁻²). The ball…',
      o: ['went down by 1 m', 'went up by 1 m', 'went down by 10 m', 'went up by 10 m'],
      x: '`W` = `m g` (`z_A` − `z_B`) = 5 J, so `z_A` − `z_B` = 5 / (0.5 × 10) = 1 m. Positive work: the weight is driving, the ball goes down. This is the reasoning of TD 4, Ex 2.' },
    'phys-c3-07': { q: 'A friction force of constant norm `f`, always opposite to the motion, acts over a distance `L`. What is its work?',
      x: 'It is opposite to the displacement at every instant: cos 180° = −1, `W` = −`f L`. Friction always does resisting (negative) work: it takes energy away from the system.' },
    'phys-c3-08': { q: 'The work of a force is a vector.',
      x: 'False. It is a scalar product: a number, in joules, positive, negative or zero. The French version of the course (p. 9) puts an arrow on the W in “Σ W”: it is a typo. In the English course, W is also the letter of the weight: the weight {W} has an arrow, the work `W_A→B` does not.' },
    'phys-c3-09': { q: 'The power of a force {F} acting on a point with velocity {v} is…',
      x: 'Course: `P` = d`W`/d`t` = {F} · {v}, in watts (1 W = 1 J/s). `F` × `d` is a work (for a force parallel to the displacement), not a power.' },
    'phys-c3-10': { q: 'A motor delivers a work of 600 J in 2 min. What is its average power?',
      x: 'Seconds first: 2 min = 120 s. `P` = `W`/Δ`t` = 600/120 = 5 W. 600/2 = 300 would be joules per minute, not watts.' },
    'phys-c3-11': { q: 'A 200 N force, parallel to the velocity and pointing the same way, acts on an object moving at 5 m·s⁻¹. What is its power?',
      x: '`P` = {F} · {v} = 200 × 5 × cos 0 = 1000 W, that is 1 kW.' },
    'phys-c3-12': { q: 'What is the kinetic energy of a 1000 kg car driving at 36 km/h?',
      x: 'First in m·s⁻¹: 36/3.6 = 10 m·s⁻¹. `E_k` = ½ `m v`² = ½ × 1000 × 100 = 50,000 J. With 36 instead of 10, you would get 648,000 J: always convert before computing.' },
    'phys-c3-13': { q: 'What does the work-kinetic energy theorem say between two points A and B?',
      o: ['the change in `E_k` equals the sum of the works of all the forces', 'the change in `E_k` equals the work of the weight only', '`E_k` stays constant', 'the change in `E_k` is zero if there is friction'],
      x: 'Σ`W`<sub>i</sub> = Δ`E_k` = ½ `m v_B`² − ½ `m v_A`². All forces count, driving ones (positive work) as well as resisting ones (negative work). If the sum of the works is positive, the system speeds up.' },
    'phys-c3-14': { q: 'If the speed of an object doubles, its kinetic energy is…',
      o: ['multiplied by 4', 'multiplied by 2', 'unchanged', 'multiplied by √2'],
      x: '`E_k` = ½ `m v`² varies as the square of the speed: (2`v`)² = 4`v`². At 100 km/h, a car has 4 times more kinetic energy than at 50 km/h.' },
    'phys-c3-15': { q: 'An object falls freely from a height of 5 m, with no initial velocity (`g` = 10 m·s⁻²). At what speed does it hit the ground?',
      x: 'Work-kinetic energy theorem, only the weight does work: ½ `m v`² − 0 = `m g h`, so `v` = √(2`g h`) = √100 = 10 m·s⁻¹. 2`g h` = 100 is `v`², not `v`: do not forget the square root.' },
    'phys-c3-16': { q: 'A 4 kg trolley starts from rest on horizontal ground. A driving force of 10 N and a friction force of 2 N, opposite to the motion, act over 4 m. What is its speed then?',
      x: 'The weight and the reaction force, perpendicular to the displacement, do no work. Work-kinetic energy theorem: ½ × 4 × `v`² − 0 = 10 × 4 − 2 × 4 = 32 J, so `v`² = 16 and `v` = 4 m·s⁻¹. Forgetting friction gives √20 ≈ 4.5 m·s⁻¹.' },
    'phys-c3-17': { q: 'A force is called conservative if…',
      o: ['its work between two points does not depend on the path followed', 'it keeps the speed of the system constant', 'it is constant', 'its work is always zero'],
      x: 'Definition of the course: the work of a conservative force between A and B depends only on A and B, not on the path. It is then derived from a potential energy. The weight is conservative: its work only depends on the difference in height.' },
    'phys-c3-18': { q: 'Which of these forces are conservative?',
      o: ['the weight', 'friction from a fluid', 'a friction force of constant norm', 'the gravitational force'],
      x: 'The work of the weight, and more generally of gravity, only depends on the start and end positions. Friction forces are non-conservative: their work is always negative, and the longer the path, the larger it is in absolute value; they dissipate energy.' },
    'phys-c3-19': { q: 'What is the gravitational potential energy of a 2 kg object placed 3 m above the ground? (`E_p` = 0 on the ground, `g` = 10 m·s⁻²)',
      x: '`E_p` = `m g h` = 2 × 10 × 3 = 60 J, with `h` the height above the ground, where we chose `E_p` = 0.' },
    'phys-c3-20': { q: 'For a conservative force, how is its work from A to B related to the potential energy?',
      o: ['`W_A→B` = −Δ`E_p` = `E_p`(A) − `E_p`(B)', '`W_A→B` = Δ`E_p` = `E_p`(B) − `E_p`(A)', '`W_A→B` = `E_p`(B)', '`W_A→B` = 0'],
      x: 'Course: `W` = −Δ`E_p`. Check with the weight: `W` = `m g` (`z_A` − `z_B`) = `E_p`(A) − `E_p`(B). When the object goes down, its potential energy decreases and the weight does positive work.' },
    'phys-c3-21': { q: 'The mechanical energy of a system is…',
      o: ['`E_M` = `E_k` + `E_p`', '`E_M` = `E_k` − `E_p`', '`E_M` = `E_k` × `E_p`', '`E_M` = ½ `m v`² only'],
      x: '`E_M` = `E_k` + `E_p`. When only conservative forces do work, it stays constant: what one loses, the other gains.' },
    'phys-c3-22': { q: 'A small ball slides without friction down a ramp, from the top A to the bottom B. What happens?',
      o: ['`E_k` increases, `E_p` decreases, `E_M` stays constant', '`E_k` and `E_p` both increase', '`E_M` decreases', '`E_k` stays constant'],
      x: 'Without friction, the reaction force is perpendicular to the trajectory and does no work; only the weight does work, and it is conservative: `E_M` is conserved. The ball goes down, `E_p` decreases, so `E_k` increases by the same amount (TD 4, Ex 4).' },
    'phys-c3-23': { q: 'A small ball passes A at 3 m·s⁻¹, then slides without friction down to B, 0.8 m lower (`g` = 10 m·s⁻²). What is its speed at B?',
      x: 'Conservation of mechanical energy: ½ `m v_A`² + `m g h` = ½ `m v_B`², so `v_B`² = `v_A`² + 2`g h` = 9 + 16 = 25 and `v_B` = 5 m·s⁻¹. Speeds do not add up: 3 + 4 = 7 is wrong, it is the energies that add up.' },
    'phys-c3-24': { q: 'Without friction, the speed of an object at the bottom of a slope depends on the shape of the slope.',
      x: 'False. With conservation of mechanical energy, ½ `m v`² only depends on the starting speed and the difference in height. The shape of the slope changes the duration of the trip and the direction of the velocity, not its norm at the end.' },
    'phys-c3-25': { q: 'With friction, between A and B, how does the mechanical energy change?',
      o: ['Δ`E_M` = `W`({f}), the work of friction, negative', 'Δ`E_M` = 0: it is always conserved', 'Δ`E_M` = `W`({W}), the work of the weight', 'Δ`E_M` = −`W`({f}): it increases'],
      x: 'Work-kinetic energy theorem: Δ`E_k` = `W`({W}) + `W`({f}) = −Δ`E_p` + `W`({f}) (the reaction force does no work). So Δ`E_M` = `W`({f}) &lt; 0: friction dissipates mechanical energy, as heat. The course does not write this formula; this is how you find it.' },
    'phys-c3-26': { q: 'A 0.1 kg ball passes B at 5 m·s⁻¹ and reaches C at 3 m·s⁻¹. BC = 2 m is horizontal, with a friction force of constant norm `f` (TD 4, Ex 4). What is `f`?',
      x: 'On horizontal BC, only friction does work: ½ `m v_C`² − ½ `m v_B`² = −`f` × BC. So `f` = `m` (`v_B`² − `v_C`²) / (2 BC) = 0.1 × (25 − 9) / 4 = 0.4 N.' },
    'phys-c3-27': { q: 'A puck slides on horizontal ground with friction, then stops. What happens to its kinetic energy?',
      o: ['it is dissipated by friction, as heat', 'it turns into gravitational potential energy', 'it stays in the puck', 'it is absorbed by the weight'],
      x: 'The ground is horizontal: the height, and so `E_p`, does not change. The mechanical energy drops by the whole kinetic energy: the (negative) work of friction dissipated it as heat.' },
    'phys-c3-28': { q: 'You want the speed of a skier at the bottom of a curved slope, without friction, knowing the drop in height. Which method is simplest?',
      o: ['conservation of mechanical energy', 'Newton’s second law, projected on fixed axes', 'integrating the acceleration twice', 'Newton’s third law'],
      x: 'On a curved slope, the reaction force changes direction at every point: projecting the second law gets complicated. Energy only needs the heights: ½ `m v`² = ½ `m v_0`² + `m g h`. It gives speeds at given points; for times or a trajectory, you need the second law.' },
    'phys-c3-29': { q: 'You want the time at which an object in free fall hits the ground. Which method do you need?',
      o: ['Newton’s second law, then the equations of motion', 'the work-kinetic energy theorem alone', 'conservation of mechanical energy alone', 'Newton’s third law'],
      x: 'Energy theorems link speeds to positions, never to time. For a time, you need `y`(`t`): the second law gives {a}, you integrate twice with the initial conditions, then solve `y`(`T`) = 0.' },
    'phys-c3-30': { q: 'Which questions does an energy method (work-kinetic energy theorem, mechanical energy) answer directly?',
      o: ['the speed at a point, knowing the heights', 'the maximum height reached by an object thrown vertically', 'the duration of a trip', 'the norm of a constant friction force, knowing the distance and the speeds'],
      x: 'Energy theorems link speeds, heights, distances and forces: speed at a point, height where the speed drops to zero, friction from a loss of speed (TD 4, Ex 4). Time does not appear: for a duration, you need the equations of motion.' },

    /* ================= chapter 4: polar coordinates ================= */
    'phys-c4-01': { q: 'Polar coordinates are best suited to the study of…',
      o: ['circular motions', 'rectilinear motions', 'free fall', 'uniform motions'],
      x: 'For a circle centred on O, `r` stays constant and only θ varies: the calculations become simpler. The course says so: Cartesian coordinates suit most plane motions, except circular ones.' },
    'phys-c4-02': { q: 'In polar coordinates, a point M of the plane is located by…',
      o: ['`r` = OM and θ, the oriented angle between {u_x} and {OM}', '`x` and `y`', '`r` and the angular velocity `θ̇`', 'θ only'],
      x: '`r` is the distance from O to M, θ the oriented angle from {u_x} to {OM}. These are two numbers, like `x` and `y`; you go from one pair to the other with `x` = `r` cos θ and `y` = `r` sin θ.' },
    'phys-c4-03': { q: 'In polar coordinates, `r` is always positive.',
      x: 'True: `r` = OM is a distance. To go “to the other side” of O, it is θ that changes (by π), not the sign of `r`.' },
    'phys-c4-04': { q: 'How is {u_r} written in the Cartesian basis?',
      x: '{u_r} is the unit vector along {OM}: its components are those of {OM}, (`r` cos θ, `r` sin θ), divided by `r`. A unit vector has no factor `r`: its norm is 1.' },
    'phys-c4-05': { q: 'How is {u_θ} written in the Cartesian basis?',
      x: '{u_θ} is obtained by rotating {u_r} by +π/2, in the anti-clockwise direction. This rotation sends (`a`, `b`) to (−`b`, `a`): (cos θ, sin θ) becomes (−sin θ, cos θ). The “−” is on the sine of the {u_x} component. Check with θ = 0: {u_θ} = {u_y}.' },
    'phys-c4-06': { q: 'The vectors {u_r} and {u_θ} are fixed, like {u_x} and {u_y}.',
      x: 'False. It is a moving basis: it turns with the point M, because it depends on θ. That is why its vectors have a non-zero derivative, and why velocity and acceleration in polar coordinates have extra terms.' },
    'phys-c4-07': { q: 'The point M is on the positive `y`-axis (θ = π/2). What is {u_θ} at M?',
      x: '{u_θ} = −sin(π/2) {u_x} + cos(π/2) {u_y} = −{u_x}. On a drawing: {u_r} = {u_y} points up, and turning it a quarter turn anti-clockwise makes it point to the left.' },
    'phys-c4-08': { q: 'What is the time derivative of {u_r}?',
      x: 'Differentiate with respect to θ, then multiply by dθ/d`t` = `θ̇` (chain rule): d{u_r}/dθ = −sin θ {u_x} + cos θ {u_y} = {u_θ}, so d{u_r}/d`t` = `θ̇` {u_θ}. It is not {0}: {u_r} turns with M. Forgetting `θ̇` means mixing up the derivative with respect to θ and the derivative with respect to `t`.' },
    'phys-c4-09': { q: 'What is the time derivative of {u_θ}?',
      x: 'd{u_θ}/dθ = −cos θ {u_x} − sin θ {u_y} = −{u_r}, then multiply by `θ̇`: d{u_θ}/d`t` = −`θ̇` {u_r}. The minus sign comes from the derivative of cos θ.' },
    'phys-c4-10': { q: 'What is the derivative of {u_r} with respect to the angle θ?',
      x: 'Differentiate each component of {u_r} = cos θ {u_x} + sin θ {u_y}: −sin θ {u_x} + cos θ {u_y}, which is exactly {u_θ}. It was Exercise 2 of the November 2021 midterm. {u_x} and {u_y} are fixed: only the functions of θ are differentiated.' },
    'phys-c4-11': { q: 'θ depends on time. What is the time derivative of sin(θ(`t`))?',
      x: 'Chain rule: (sin θ)′ = `θ̇` cos θ. The factor `θ̇` is essential as soon as θ depends on time: it is what brings the `θ̇` terms into the velocity in polar coordinates.' },
    'phys-c4-12': { q: 'In polar coordinates, the position vector is written…',
      x: '{u_r} points along {OM} and OM = `r`: {OM} = `r` {u_r}, with no component on {u_θ}. θ is an angle, dimensionless: it cannot be a component of a vector in metres. The angle is “hidden” in the direction of {u_r}.' },
    'phys-c4-13': { q: '`x`(`t`) = 3 cos(ω`t`) and `y`(`t`) = 3 sin(ω`t`), in metres. How is the position vector written in polar coordinates?',
      x: '`r` = √(`x`² + `y`²) = 3 m and θ = ω`t`. So {OM} = 3 {u_r}: the information on θ is in {u_r}, which turns. You do not copy the Cartesian components onto the polar basis (TD 5, Ex 2).' },
    'phys-c4-14': { q: 'The point M has Cartesian coordinates (−2, 0), in metres. What are its polar coordinates?',
      x: '`r` = OM = 2 m, always positive. M is on the negative `x`-axis: the angle between {u_x} and {OM} is π. Check: `x` = `r` cos θ = 2 × (−1) = −2 and `y` = 2 sin π = 0.' },
    'phys-c4-15': { q: 'In polar coordinates, the velocity vector is written…',
      x: '{v} = d(`r` {u_r})/d`t` = `ṙ` {u_r} + `r` d{u_r}/d`t` = `ṙ` {u_r} + `r θ̇` {u_θ}. Forgetting that {u_r} turns gives `ṙ` {u_r} alone. Without the `r`, the term `θ̇` {u_θ} would be in rad·s⁻¹, not m·s⁻¹. This formula is asked in almost every midterm found.' },
    'phys-c4-16': { q: 'In {v} = `ṙ` {u_r} + `r θ̇` {u_θ}, where does the term `r θ̇` {u_θ} come from?',
      o: ['from the derivative of {u_r}: d{u_r}/d`t` = `θ̇` {u_θ}', 'from the derivative of `r`', 'from the derivative of a θ {u_θ} term of the position vector', 'it is added by definition of the angular velocity'],
      x: 'Differentiate the product `r` {u_r}: (d`r`/d`t`) {u_r} + `r` (d{u_r}/d`t`). The second term comes from the rotation of the basis: `r` × `θ̇` {u_θ}. At the November 2021 midterm, this derivation “explaining each step” was worth 2 points.' },
    'phys-c4-17': { q: 'What is the norm of {v} = `ṙ` {u_r} + `r θ̇` {u_θ}?',
      x: '{u_r} and {u_θ} are orthogonal unit vectors: Pythagoras, as in Cartesian coordinates. ‖{v}‖ = √(`ṙ`² + (`r θ̇`)²): the `r` is squared too.' },
    'phys-c4-18': { q: 'θ is in radians and `θ̇` in rad·s⁻¹. What is the unit of `r θ̇`?',
      x: 'The radian is dimensionless: `r θ̇` is in m × s⁻¹ = m·s⁻¹, the unit of a velocity. It is a good consistency check: each component of {v} must be in m·s⁻¹, and `r θ̇`² in m·s⁻².' },
    'phys-c4-19': { q: '`r`(`t`) = 2`t` (in m) and θ(`t`) = 3`t` (in rad). What is the velocity vector?',
      x: '`ṙ` = 2 and `θ̇` = 3, so `r θ̇` = 2`t` × 3 = 6`t`: {v} = 2 {u_r} + 6`t` {u_θ}. Writing `θ̇` alone (3) forgets the factor `r`; writing 2 {u_r} alone forgets that the basis turns.' },
    'phys-c4-20': { q: 'In polar coordinates, the acceleration vector is written…',
      x: 'It is the formula of the course, obtained by differentiating {v} = `ṙ` {u_r} + `r θ̇` {u_θ}, with d{u_r}/d`t` = `θ̇` {u_θ} and d{u_θ}/d`t` = −`θ̇` {u_r}. The −`r θ̇`² comes from the derivative of {u_θ}, the 2`ṙ θ̇` from two equal terms. Midterms often give it; above all you must know how to use it.' },
    'phys-c4-21': { q: 'In the component 2`ṙ θ̇` + `r θ̈`, where does the factor 2 come from?',
      o: ['the term `ṙ θ̇` {u_θ} appears twice: when differentiating `ṙ` {u_r} and when differentiating `r θ̇` {u_θ}', 'it is a writing convention', 'from the derivative of `θ̇`²', 'from the derivative of `r`²'],
      x: 'd(`ṙ` {u_r})/d`t` = `r̈` {u_r} + `ṙ θ̇` {u_θ}; d(`r θ̇` {u_θ})/d`t` = `ṙ θ̇` {u_θ} + `r θ̈` {u_θ} − `r θ̇`² {u_r}. The term `ṙ θ̇` {u_θ} comes out once from each derivative: 2`ṙ θ̇`.' },
    'phys-c4-22': { q: '`r`(`t`) = 2`t` (in m) and θ(`t`) = `t` (in rad). What is the radial component of the acceleration, `a_r` = `r̈` − `r θ̇`², at `t` = 1 s?',
      x: '`r̈` = 0 and `θ̇` = 1, so `a_r` = 0 − 2`t` × 1² = −2`t`, that is −2 m·s⁻² at `t` = 1 s. The minus sign is normal: this component points towards O.' },
    'phys-c4-23': { q: 'For a uniform circular motion of radius `R`, the acceleration is written, in the basis ({u_r}, {u_θ}):',
      x: 'Circular: `r` = `R` is constant, so `ṙ` = `r̈` = 0. Uniform: `θ̇` is constant, so `θ̈` = 0. What remains is {a} = −`R θ̇`² {u_r}: the acceleration points towards the centre (centripetal), it is not zero. With a “+” sign it would point outwards.' },
    'phys-c4-24': { q: 'A point moves along a circle of radius `R`, and its speed changes (accelerated or decelerated motion). What is its acceleration in the basis ({u_r}, {u_θ})?',
      x: '`r` = `R` is constant: `ṙ` = `r̈` = 0. What remains is −`R θ̇`² on {u_r}, present as soon as the point turns, and `R θ̈` on {u_θ}. Accelerated or decelerated, the expression is the same: only the sign of `θ̈` relative to `θ̇` changes.' },
    'phys-c4-25': { q: 'A point moves along a circle of radius 2 m at a constant angular velocity ω = 3 rad·s⁻¹. What is the norm of its acceleration?',
      x: '‖{a}‖ = `R` ω² = 2 × 9 = 18 m·s⁻². Uniform does not mean zero acceleration: the direction of the velocity keeps changing. `R` ω = 6 m·s⁻¹ is the speed.' },
    'phys-c4-26': { q: 'In a uniform circular motion, the acceleration is…',
      o: ['pointing towards the centre, with norm `v`²/`R`', 'zero, since the speed is constant', 'tangent to the circle', 'pointing out of the circle'],
      x: 'With `v` = `R θ̇`: ‖{a}‖ = `R θ̇`² = `v`²/`R`, along −{u_r}, so towards the centre. What is constant is the norm of the velocity, not the vector: its direction turns, and that takes an acceleration.' },
    'phys-c4-27': { q: 'A satellite is on a circular orbit of radius `r` around the Earth, of mass `M_T`, subject to gravity only (TD 5, Ex 3). What is its speed?',
      x: 'Newton’s second law in the geocentric reference frame: `m` {a} = −`G M_T` `m`/`r`² {u_r}. On {u_θ}: `r θ̈` = 0, the motion is uniform. On {u_r}: `v`²/`r` = `G M_T`/`r`², so `v` = √(`G M_T`/`r`). The mass of the satellite cancels out.' },
    'phys-c4-28': { q: 'For a circular motion centred on O, `ṙ` = 0 and `r̈` = 0.',
      x: 'True: `r` = `R` is constant, its derivatives are zero. It is the first line of any “circular motion” question: it removes `ṙ` and `r̈` from the formulas of the velocity and the acceleration.' },
    'phys-c4-29': { q: 'A point has polar coordinates `r` = 2 m and θ = π/2. What are its Cartesian coordinates?',
      x: '`x` = `r` cos θ = 2 cos(π/2) = 0 and `y` = `r` sin θ = 2 sin(π/2) = 2. The point is on the positive `y`-axis, 2 m from O.' },
    'phys-c4-30': { q: 'The point M has Cartesian coordinates (1, 1), in metres. What are its polar coordinates?',
      x: '`r` = √(`x`² + `y`²) = √2 m (not 1 + 1 = 2). tan θ = `y`/`x` = 1, with M in the first quadrant: θ = π/4.' },
    'phys-c4-31': { q: 'In cylindrical coordinates, what must you add to the polar coordinates (`r`, θ) to locate a point in space?',
      o: ['the height `z`, on a fixed axis {u_z}', 'a second angle', 'the angular velocity `θ̇`', 'nothing: they are the same coordinates'],
      x: 'Cylindrical = polar in the (`x`, `y`) plane + the height `z`: {OM} = `r` {u_r} + `z` {u_z}, with {u_z} fixed. A second angle is the case of spherical coordinates. The coordinate help sheet on Moodle shows both; the course does not go into them.' }
  };
  if (SLOPE) { E['phys-c2-27'].fig = SLOPE; E['phys-c2-28'].fig = SLOPE; }

  /* same notation as the French file: {v} vector, `x` quantity, subscript after “_” */
  function sub(s) { return /^[xyzrθρ]$/.test(s) ? '<var>' + s + '</var>' : s; }
  function m(s) {
    return String(s)
      .replace(/\{([^{}_]+)(?:_([^{}]+))?\}/g, function (_, b, i) { return '<var class="vec">' + b + '</var>' + (i ? '<sub>' + sub(i) + '</sub>' : ''); })
      .replace(/`([^`_]+)(?:_([^`]+))?`/g, function (_, b, i) { return '<var>' + b + '</var>' + (i ? '<sub>' + sub(i) + '</sub>' : ''); });
  }
  Object.keys(E).forEach(function (id) {
    var e = E[id];
    if (e.q) e.q = m(e.q);
    if (e.x) e.x = m(e.x);
    if (e.o) e.o = e.o.map(m);
  });
  REV.i18n.qcm(E);
})();
